SELECT DATE_FORMAT(c.signup_date, 'yyyy-MM') AS signup_month, CASE WHEN c.credit_limit >= 16600 THEN 'high' WHEN c.credit_limit >= 3800 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MIN(o.order_date) AS min_order_date FROM orders o FULL OUTER JOIN customers c ON c.id = o.customer_id JOIN stores s ON o.store_id = s.id GROUP BY DATE_FORMAT(c.signup_date, 'yyyy-MM'), CASE WHEN c.credit_limit >= 16600 THEN 'high' WHEN c.credit_limit >= 3800 THEN 'mid' ELSE 'low' END ORDER BY min_order_date, credit_limit_bucket;
